@startuml

class Driver {
  + Name : string
  + ID : int
  + IsOnSickLeave : boolean
}

class Bus {
  + LicensePlate : string
  + InRepairShop : boolean
}

class Route {
  + Number : int
  + MaxNumber : int = 9999
}

class Shift {
  + Type : string
  + TimeSlot : string
}

class Schedule {
  + RouteNumber : int
  + DriverID : int
  + BusLicensePlate : string
  + ShiftType : string
  + Date : date
}

Driver "0..*" -- "1" Schedule
Bus "0..*" -- "1" Schedule
Route "0..*" -- "1" Schedule

@enduml

